  </main>

  <footer class="site-footer"><div class="container"><div class="footer-main"><div class="footer-about"><a href="#/" class="brand" @click.prevent="navigate('home')"><img src="/brand.svg" alt="" /><span>SuperPower<small>BROWSER</small></span></a><p>独立每一个环境，连接每一份可能。<br />为多账号运营与团队协作，构建清晰的工作空间。</p></div><div class="footer-links"><h3>探索产品</h3><button @click="scrollToSection('features')">浏览器环境</button><button @click="scrollToSection('ai')">AI 工作台</button><button @click="open('download')">客户端下载</button></div><div class="footer-links"><h3>帮助与支持</h3><button @click="navigate('help')">入门指南</button><button @click="navigate('help')">常见问题</button><button @click="open('contact')">联系我们</button></div><div class="footer-links"><h3>与我们联系</h3><span>微信 {{ config.wechat }}</span><span>电话：{{ config.phone || '待公布' }}</span><span>邮箱：{{ config.email || '待公布' }}</span></div></div><div class="footer-bottom"><span>© {{ new Date().getFullYear() }} SuperPower Browser. <span v-if="config.icp">{{ config.icp }}</span></span><div><button @click="open('terms')">使用说明</button><span>·</span><button @click="open('privacy')">隐私说明</button><span class="footer-tag"><i></i> BUILT FOR FOCUS</span></div></div></div></footer>
  <aside class="floating-support" aria-label="快捷支持"><button @click="open('contact')"><Icon name="message" :size="21" /><span>微信咨询</span></button><span></span><button @click="navigate('help')"><Icon name="help" :size="21" /><span>帮助中心</span></button></aside>
  <SiteModal :kind="modal" :config="config" @close="modal = ''" @open="open" @copy="copy" />
  <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Icon name="check" :size="18" />{{ toast }}</div></Transition>
</template>
